package live.linghe.privateinput;
import android.content.Context;import android.os.SystemClock;import android.util.AtomicFile;import java.io.*;import java.math.BigInteger;import java.util.*;import org.json.*;
/** Immutable replacement for v2 recency score. Built on background IO once;
 * typing performs O(1) map lookup, no disk/model merge/network. */
final class CloudLearningRankSnapshot {
 final String modelVersion;private final Map<String,Double> scores;private final Map<String,BigInteger> deletions;private final long expiresUptime;private final String privacy;
 private CloudLearningRankSnapshot(Map<String,Double> scores,Map<String,BigInteger> deletions,long expires,String privacy,String modelVersion){this.modelVersion=modelVersion;this.deletions=Collections.unmodifiableMap(new HashMap<>(deletions));this.scores=Collections.unmodifiableMap(new HashMap<>(scores));expiresUptime=expires;this.privacy=privacy;}
 boolean valid(Context context){return SystemClock.elapsedRealtime()<expiresUptime&&privacy.equals(PersonalReset.generation(context))&&context.getSharedPreferences("sync-consent",0).getBoolean(CloudLearningStore.ENABLED,false)&&context.getSharedPreferences("sync-consent",0).getBoolean(CloudLearningStore.RANK,false)&&context.getSharedPreferences("sync-consent",0).getBoolean(CloudLearningStore.VALID,false);}
 double score(String reading,String text){return scores.getOrDefault(LearningModel.canonical(reading.toLowerCase(Locale.ROOT).trim()+'\u001f'+text),0.0);}
 BigInteger deletionGeneration(String reading,String text){return deletions.get(LearningRelearnGate.key(reading,text));}
 static Map<String,BigInteger> deletionIndex(JSONObject rank)throws Exception{Map<String,BigInteger> result=new HashMap<>();JSONObject fences=rank.getJSONObject("fences");Iterator<String> keys=fences.keys();while(keys.hasNext()){String key=keys.next();JSONObject row=fences.getJSONObject(key);if(row.getBoolean("deleted"))result.put(key,CloudLearningState.number(row,"generation"));}return Collections.unmodifiableMap(result);}
 static CloudLearningRankSnapshot read(Context context,List<LearningModel.Entry> current,String producer)throws Exception{
  if(!context.getSharedPreferences("sync-consent",0).getBoolean(CloudLearningStore.VALID,false)||!context.getSharedPreferences("sync-consent",0).getBoolean(CloudLearningStore.ENABLED,false))return null;File directory=new File(new File(context.getFilesDir(),"Shared"),"CloudLearning");String data=AppFiles.locked(directory,"state.lock",()->AppFiles.readOptional(new AtomicFile(new File(directory,"rank-v1.json")),8*1024*1024));if(data==null)return null;JSONObject rank=LosslessJson.object(data,8*1024*1024);String checksum=rank.getString("checksum");rank.remove("checksum");if(!CloudLearningCanonical.hash(rank).equals(checksum))throw new IOException("cloud rank checksum");String privacy=PersonalReset.generation(context);long remaining=LosslessJson.unsigned(rank.get("expiresAt")).longValueExact()-System.currentTimeMillis()/1000;LearningCapacityMetadata.archive(rank,1,2);if(!privacy.equals(rank.getString("privacy"))||remaining<=0||remaining>7*86400||!PersonalLexicon.uuid(rank.getString("producer")).equals(PersonalLexicon.uuid(producer)))return null;
  Map<String,List<LearningModel.Entry>> local=new LinkedHashMap<>();local.put(PersonalLexicon.uuid(producer),current);return new CloudLearningRankSnapshot(build(rank,local),deletionIndex(rank),SystemClock.elapsedRealtime()+remaining*1000,privacy,rank.optString("modelVersion",""));
 }
 /** Fold local highest generation and same-generation deletion OR before any
  * positive overlay. A current cloud tombstone fences same/older local rows. */
 static Map<String,Double> build(JSONObject rank,Map<String,List<LearningModel.Entry>> local)throws Exception{
  JSONObject terms=rank.getJSONObject("terms"),fences=rank.getJSONObject("fences"),represented=rank.getJSONObject("represented");LearningCapacityProfiles.Profile profile=rank.has("version")?LearningCapacityMetadata.archive(rank,1,2):LearningCapacityProfiles.LEGACY_5000;if(terms.length()>profile.modelTermRows||fences.length()>profile.cloudFenceKeys||local.size()>LearningCapacityProfiles.EXPANDED_10000.producersPerDevice)throw new IOException("cloud rank bound");Map<String,BigInteger> generations=new HashMap<>();Set<String> deleted=new HashSet<>();
  Map<String,Map<String,LearningModel.Entry>> indexed=new HashMap<>();for(Map.Entry<String,List<LearningModel.Entry>> source:local.entrySet()){if(source.getValue().size()>LearningCapacityProfiles.EXPANDED_10000.producerTermRows)throw new IOException("cloud local bound");Map<String,LearningModel.Entry> byID=new HashMap<>();for(LearningModel.Entry row:source.getValue())if(byID.put(row.id(),row)!=null)throw new IOException("cloud duplicate local row");indexed.put(PersonalLexicon.uuid(source.getKey()),byID);}
  for(List<LearningModel.Entry> entries:local.values())for(LearningModel.Entry row:entries){BigInteger old=generations.get(row.id());if(old==null||row.generation.compareTo(old)>0){generations.put(row.id(),row.generation);if(row.deleted)deleted.add(row.id());else deleted.remove(row.id());}else if(row.generation.equals(old)&&row.deleted)deleted.add(row.id());}
  Set<String> keys=new HashSet<>(generations.keySet());Iterator<String> names=terms.keys();while(names.hasNext())keys.add(names.next());Map<String,Double> result=new HashMap<>();
  for(String key:keys){JSONObject fence=fences.optJSONObject(key),term=terms.optJSONObject(key);BigInteger cloud=fence==null?BigInteger.ZERO:CloudLearningState.number(fence,"generation"),own=generations.get(key);boolean cloudDeleted=fence!=null&&fence.optBoolean("deleted"),blocked=own!=null&&own.compareTo(cloud)>=0&&(own.equals(cloud)&&cloudDeleted||deleted.contains(key));long weight=term==null?0:CloudLearningState.number(term,"weight").longValueExact();if(blocked){result.put(key,0.0);continue;}if(own!=null&&own.compareTo(cloud)>0)weight=0;
   for(Map.Entry<String,Map<String,LearningModel.Entry>> source:indexed.entrySet()){JSONObject baseline=represented.optJSONObject(source.getKey());LearningModel.Entry row=source.getValue().get(key);if(row!=null&&!row.deleted&&row.generation.equals(own)&&row.generation.compareTo(cloud)>=0){JSONObject previous=baseline==null?null:baseline.optJSONObject(key);long before=0;if(previous!=null&&CloudLearningState.number(previous,"generation").equals(row.generation))before=LosslessJson.unsigned(previous.getJSONObject("counts").opt(PersonalLexicon.uuid(source.getKey()))==null?0:previous.getJSONObject("counts").get(PersonalLexicon.uuid(source.getKey()))).longValueExact();long count=0;for(Map.Entry<String,Long> component:row.counts.entrySet())if(component.getKey().equalsIgnoreCase(source.getKey()))count=Math.max(count,component.getValue());weight=Math.min(200000,weight+Math.min(1000,Math.max(0,count-before))*1000);}}
   result.put(key,Math.min(.999,Math.log1p(Math.max(0,weight))/Math.log1p(200000)));
  }
  return result;
 }
}
